"""Handcrafted flashcard phrases and sentences for the English tutor app.

Every entry is a tuple (en, ru, uses), where ``uses`` is a list of lowercase
lemmas that the phrase or sentence helps to practise.
"""
from __future__ import annotations


def T(en: str, ru: str, uses: str) -> tuple[str, str, list[str]]:
    """Build a card tuple; ``uses`` is a space-separated string of lemmas."""
    return (en, ru, uses.lower().split())


